import { getDb } from './db'
import { DEFAULT_DRILL_CONFIG, type DrillConfig } from '../engine/types'

export interface ProfileRecord {
  id: string
  name: string
  config: DrillConfig
  createdAt: number
  updatedAt: number
}

export const DEFAULT_PROFILE_NAME = 'Default'

function newId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `prof-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function buildDefaultProfile(
  overrides?: Partial<DrillConfig>,
): ProfileRecord {
  const now = Date.now()
  return {
    id: newId(),
    name: DEFAULT_PROFILE_NAME,
    config: { ...DEFAULT_DRILL_CONFIG, ...overrides },
    createdAt: now,
    updatedAt: now,
  }
}

export async function listProfiles(): Promise<ProfileRecord[]> {
  const db = getDb()
  if (!db) return []
  try {
    return await db.profiles.orderBy('createdAt').toArray()
  } catch {
    return []
  }
}

export async function getProfile(id: string): Promise<ProfileRecord | null> {
  const db = getDb()
  if (!db) return null
  try {
    return (await db.profiles.get(id)) ?? null
  } catch {
    return null
  }
}

export async function saveProfile(profile: ProfileRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.profiles.put({ ...profile, updatedAt: Date.now() })
  } catch {
    /* ignore */
  }
}

export async function deleteProfile(id: string): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.profiles.delete(id)
  } catch {
    /* ignore */
  }
}

export async function ensureAtLeastOneProfile(
  seedFromOverrides?: Partial<DrillConfig>,
): Promise<ProfileRecord> {
  const existing = await listProfiles()
  if (existing.length > 0) return existing[0]
  const seed = buildDefaultProfile(seedFromOverrides)
  await saveProfile(seed)
  return seed
}

import { useEffect, useRef, useState } from 'react'
import QRCode from 'qrcode'
import jsQR from 'jsqr'
import { createPeer, type PeerHandle, type PeerState } from '../phone/peer'
import { buildPhoneUrl } from '../phone/pair-url'
import { tryDecodeOffer, tryEncodeOffer } from '../phone/qr'
import type { PhoneMessage } from '../phone/wire'
import { loadSettings } from '../store/settings'

interface PairScreenProps {
  onClose: () => void
  /** Override `navigator.mediaDevices.getUserMedia` for tests. */
  getUserMedia?: (constraints: MediaStreamConstraints) => Promise<MediaStream>
}

export type PairMode = 'qr' | 'manual'
export type PairQrState =
  | 'preparing-offer'
  | 'showing-offer'
  | 'scanning-answer'
  | 'connected'
  | 'error'

/**
 * Phase 2b.2 — laptop-side pairing.
 *
 * QR mode is the default: the laptop renders an offer QR containing
 * `…/phone#offer=<compressed-sdp>`. The user scans it with their phone,
 * the phone renders an answer QR, and the laptop's webcam decodes that
 * answer to complete the handshake.
 *
 * Manual mode is the 2b.1 textarea fallback. It auto-activates when the
 * webcam is denied/unavailable or when the SDP is too big for one QR.
 */
export function PairScreen({ onClose, getUserMedia }: PairScreenProps) {
  const peerRef = useRef<PeerHandle | null>(null)
  const videoRef = useRef<HTMLVideoElement | null>(null)
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const qrCanvasRef = useRef<HTMLCanvasElement | null>(null)
  const scanRafRef = useRef<number | null>(null)
  const streamRef = useRef<MediaStream | null>(null)

  const [mode, setMode] = useState<PairMode>('qr')
  const [qrState, setQrState] = useState<PairQrState>('preparing-offer')
  const [peerState, setPeerState] = useState<PeerState>('idle')
  const [phoneUrl, setPhoneUrl] = useState<string | null>(null)
  const [lanIp, setLanIp] = useState<string | null>(null)
  const [offerSdp, setOfferSdp] = useState('')
  const [answerSdp, setAnswerSdp] = useState('')
  const [autoFallbackReason, setAutoFallbackReason] = useState<string | null>(
    null,
  )
  const [err, setErr] = useState<string | null>(null)
  const [startedAt, setStartedAt] = useState<number | null>(null)
  const [lastCommit, setLastCommit] = useState<{
    receivedAt: number
    sentAt: number
  } | null>(null)

  // --- Setup: load settings, create peer, generate offer, attempt QR ---
  useEffect(() => {
    let cancelled = false
    void (async () => {
      const s = await loadSettings()
      if (cancelled) return
      const ip = s.laptopLanIp?.trim() ?? ''
      setLanIp(ip || null)

      const peer = createPeer()
      peerRef.current = peer
      peer.onStateChange((next) => {
        if (cancelled) return
        setPeerState(next)
        if (next === 'connected') {
          setQrState('connected')
          // Reset the RTT baseline so "Last commit received at +Xms" is the
          // pure phone→laptop send time the M5 manual gate budgets at <200ms,
          // not the offer-creation + scan + handshake elapsed.
          setStartedAt(Date.now())
        }
      })
      peer.onMessage((m: PhoneMessage) => {
        if (m.type === 'commit') {
          setLastCommit({ receivedAt: Date.now(), sentAt: m.t })
        }
      })

      setStartedAt(Date.now())
      try {
        const sdp = await peer.createOffer()
        if (cancelled) return
        setOfferSdp(sdp)
        const enc = await tryEncodeOffer(sdp)
        if (!enc.ok) {
          setMode('manual')
          setAutoFallbackReason(
            `Pairing payload (${enc.byteLength} bytes) is too large for one QR — using manual paste.`,
          )
          setQrState('showing-offer')
          return
        }
        if (!ip) {
          setMode('manual')
          setAutoFallbackReason(
            'Set your laptop’s LAN IP in Settings to enable QR pairing. Using manual paste.',
          )
          setQrState('showing-offer')
          return
        }
        const url = buildPhoneUrl(
          {
            protocol: window.location.protocol,
            lanIp: ip,
            port: window.location.port,
          },
          enc.payload,
        )
        setPhoneUrl(url)
        setQrState('showing-offer')
      } catch (e) {
        setErr(e instanceof Error ? e.message : String(e))
        setQrState('error')
      }
    })()
    return () => {
      cancelled = true
      stopScanning()
      peerRef.current?.close()
    }
  }, [])

  // --- Draw the offer QR onto its canvas once we have a phoneUrl ---
  useEffect(() => {
    if (!phoneUrl) return
    const canvas = qrCanvasRef.current
    if (!canvas) return
    void QRCode.toCanvas(canvas, phoneUrl, {
      margin: 1,
      width: 320,
      errorCorrectionLevel: 'L',
    }).catch((e: unknown) => {
      setErr(e instanceof Error ? e.message : String(e))
    })
  }, [phoneUrl])

  function stopScanning(): void {
    if (scanRafRef.current !== null) {
      cancelAnimationFrame(scanRafRef.current)
      scanRafRef.current = null
    }
    if (streamRef.current) {
      for (const t of streamRef.current.getTracks()) t.stop()
      streamRef.current = null
    }
  }

  async function handleStartScan(): Promise<void> {
    setErr(null)
    const gum =
      getUserMedia ??
      navigator.mediaDevices?.getUserMedia.bind(navigator.mediaDevices)
    if (!gum) {
      setMode('manual')
      setAutoFallbackReason('No camera available — use manual pairing below.')
      return
    }
    let stream: MediaStream
    try {
      stream = await gum({ video: { facingMode: 'user' } })
    } catch (e) {
      setMode('manual')
      setAutoFallbackReason(
        e instanceof Error && e.name === 'NotAllowedError'
          ? 'Camera blocked — use manual pairing below.'
          : `Camera unavailable (${e instanceof Error ? e.message : String(e)}) — use manual pairing below.`,
      )
      return
    }
    streamRef.current = stream
    const video = videoRef.current
    if (!video) return
    video.srcObject = stream
    await video.play().catch(() => {})
    setQrState('scanning-answer')
    scheduleScan()
  }

  function scheduleScan(): void {
    if (scanRafRef.current !== null) return
    // Decision memo §"jsqr scan loop" budgets ~10 fps. raf would run ~60.
    let lastDecodeAt = 0
    const decodeIntervalMs = 100
    const tick = () => {
      scanRafRef.current = null
      const video = videoRef.current
      const canvas = canvasRef.current
      if (!video || !canvas) return
      const now = performance.now()
      if (now - lastDecodeAt < decodeIntervalMs) {
        scanRafRef.current = requestAnimationFrame(tick)
        return
      }
      const w = video.videoWidth
      const h = video.videoHeight
      if (!w || !h) {
        scanRafRef.current = requestAnimationFrame(tick)
        return
      }
      canvas.width = w
      canvas.height = h
      const ctx = canvas.getContext('2d')
      if (!ctx) return
      ctx.drawImage(video, 0, 0, w, h)
      const image = ctx.getImageData(0, 0, w, h)
      lastDecodeAt = now
      const result = jsQR(image.data, w, h)
      if (result && result.data) {
        void handleDecodedAnswer(result.data)
        return
      }
      scanRafRef.current = requestAnimationFrame(tick)
    }
    scanRafRef.current = requestAnimationFrame(tick)
  }

  async function handleDecodedAnswer(payload: string): Promise<void> {
    const dec = await tryDecodeOffer(payload)
    if (!dec.ok) {
      // Any QR in the camera's view lands here (stickers, screensavers,
      // wifi-config QRs). Resume the scan loop so the operator doesn't
      // have to reload to retry.
      scheduleScan()
      return
    }
    stopScanning()
    setAnswerSdp(dec.sdp)
    try {
      await peerRef.current?.acceptAnswer(dec.sdp)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
      // Decoded payload was wire-valid but the SDP was junk. Re-enter the
      // scan loop instead of dead-ending — the user can re-point at the
      // phone or fall back to manual pairing from the toggle.
      setQrState('showing-offer')
      void handleStartScan()
    }
  }

  async function handleManualAcceptAnswer(): Promise<void> {
    setErr(null)
    if (!answerSdp.trim()) {
      setErr('Paste the answer SDP from the phone.')
      return
    }
    try {
      await peerRef.current?.acceptAnswer(answerSdp)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  function toggleMode(): void {
    setMode((m) => {
      if (m === 'qr') stopScanning()
      return m === 'qr' ? 'manual' : 'qr'
    })
  }

  const sinceStart =
    startedAt !== null && lastCommit
      ? lastCommit.receivedAt - startedAt
      : null

  return (
    <div className="screen pair-screen">
      <header className="settings-header">
        <h1>Pair phone</h1>
        <button type="button" className="link" onClick={onClose}>
          Close
        </button>
      </header>

      <p className="hint">
        QR pairing (Phase 2b.2). Manual paste remains available as a fallback.
      </p>

      <div className="profile-actions">
        <button
          type="button"
          className="link"
          onClick={toggleMode}
          aria-label="toggle pair mode"
        >
          {mode === 'qr' ? 'Show manual pairing' : 'Back to QR pairing'}
        </button>
      </div>

      {autoFallbackReason && mode === 'manual' && (
        <div className="banner info" role="status">
          {autoFallbackReason}
        </div>
      )}

      {mode === 'qr' ? (
        <QrPanel
          qrState={qrState}
          phoneUrl={phoneUrl}
          lanIp={lanIp}
          qrCanvasRef={qrCanvasRef}
          videoRef={videoRef}
          canvasRef={canvasRef}
          onStartScan={() => void handleStartScan()}
        />
      ) : (
        <ManualPanel
          phoneUrl={phoneUrlForManual(lanIp)}
          offerSdp={offerSdp}
          answerSdp={answerSdp}
          peerState={peerState}
          onAnswerChange={setAnswerSdp}
          onAccept={() => void handleManualAcceptAnswer()}
        />
      )}

      <section className="settings-section">
        <h2>Status</h2>
        <p>
          Connection: <strong data-testid="pair-state">{qrState}</strong>{' '}
          (peer: <span data-testid="peer-state">{peerState}</span>)
        </p>
        {lastCommit && (
          <p data-testid="last-commit">
            Last commit received at +{sinceStart}ms (phone clock t=
            {lastCommit.sentAt}).
          </p>
        )}
      </section>

      {err && (
        <div className="banner warn" role="alert">
          {err}
        </div>
      )}
    </div>
  )
}

function QrPanel({
  qrState,
  phoneUrl,
  lanIp,
  qrCanvasRef,
  videoRef,
  canvasRef,
  onStartScan,
}: {
  qrState: PairQrState
  phoneUrl: string | null
  lanIp: string | null
  qrCanvasRef: React.RefObject<HTMLCanvasElement | null>
  videoRef: React.RefObject<HTMLVideoElement | null>
  canvasRef: React.RefObject<HTMLCanvasElement | null>
  onStartScan: () => void
}) {
  return (
    <>
      <section className="settings-section">
        <h2>1. Scan with your phone</h2>
        {phoneUrl ? (
          <>
            <canvas ref={qrCanvasRef} data-testid="offer-qr" />
            <p className="hint">
              Or open <code data-testid="phone-url">{phoneUrl}</code> manually.
            </p>
          </>
        ) : (
          <p className="hint" data-testid="qr-pending">
            {lanIp ? 'Preparing offer…' : 'Set your laptop’s LAN IP in Settings to render a QR.'}
          </p>
        )}
      </section>

      <section className="settings-section">
        <h2>2. Scan the phone's reply</h2>
        {qrState === 'scanning-answer' || qrState === 'connected' ? (
          <>
            <video
              ref={videoRef}
              data-testid="answer-video"
              playsInline
              muted
              style={{ maxWidth: 320 }}
            />
            <canvas
              ref={canvasRef}
              data-testid="answer-canvas"
              style={{ display: 'none' }}
            />
          </>
        ) : (
          <button
            type="button"
            className="primary"
            onClick={onStartScan}
            disabled={qrState !== 'showing-offer'}
            aria-label="start scan"
          >
            I scanned the QR — turn on camera
          </button>
        )}
      </section>
    </>
  )
}

function ManualPanel({
  phoneUrl,
  offerSdp,
  answerSdp,
  peerState,
  onAnswerChange,
  onAccept,
}: {
  phoneUrl: string | null
  offerSdp: string
  answerSdp: string
  peerState: PeerState
  onAnswerChange: (v: string) => void
  onAccept: () => void
}) {
  return (
    <>
      <section className="settings-section">
        <h2>1. Open the phone companion page</h2>
        {phoneUrl ? (
          <p>
            On your phone, open <code data-testid="phone-url">{phoneUrl}</code>.
          </p>
        ) : (
          <p className="hint">
            Set your laptop's LAN IP in Settings to see the phone URL here.
          </p>
        )}
      </section>

      <section className="settings-section">
        <h2>2. Offer SDP (copy onto the phone)</h2>
        <textarea
          aria-label="offer SDP"
          rows={6}
          value={offerSdp}
          readOnly
          placeholder="(generating…)"
        />
      </section>

      <section className="settings-section">
        <h2>3. Paste the phone's answer SDP</h2>
        <textarea
          aria-label="answer SDP"
          rows={6}
          value={answerSdp}
          onChange={(e) => onAnswerChange(e.target.value)}
          placeholder="v=0…"
        />
        <button
          type="button"
          className="primary"
          onClick={onAccept}
          disabled={peerState !== 'awaiting_answer'}
        >
          Connect
        </button>
      </section>
    </>
  )
}

function phoneUrlForManual(lanIp: string | null): string | null {
  if (!lanIp) return null
  return buildPhoneUrl(
    {
      protocol: window.location.protocol,
      lanIp,
      port: window.location.port,
    },
    null,
  )
}

import { StrictMode, Suspense, lazy } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import App from './App.tsx'

// eslint-disable-next-line react-refresh/only-export-components
const PhoneApp = lazy(() =>
  import('./phone/PhoneApp.tsx').then((m) => ({ default: m.PhoneApp })),
)

const isPhoneRoute =
  typeof window !== 'undefined' &&
  /^\/phone(\/|$)/.test(window.location.pathname)

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    {isPhoneRoute ? (
      <Suspense fallback={<div className="screen">Loading phone…</div>}>
        <PhoneApp />
      </Suspense>
    ) : (
      <App />
    )}
  </StrictMode>,
)

// Phase 2b.2 verification driver
//
// Gate-grade automated checks (do not depend on a live WebRTC handshake):
//   C1. /phone with no URL fragment renders the manual paste UI (the 2b.1
//       fallback path that survived 2b.2).
//   C3. /phone#offer=!!! (malformed) renders the manual paste UI with the
//       "QR payload could not be read" banner.
//   C5. Pair view "Show manual pairing" toggle flips to the 2b.1 manual
//       textareas.
//
// Best-effort automated checks (depend on RTCPeerConnection completing ICE
// gathering, which headless chromium without UDP/STUN may not do — same
// documented concession as 2b.1's C5; manual real-device QA covers these):
//   C2. /phone#offer=<base64url-gzipped-sdp> renders the answer QR
//       (auto-apply path). The QR canvas is non-empty.
//   C4. Pair view (laptop) defaults to QR mode and renders the offer QR
//       canvas with a phoneUrl that contains `#offer=`.
//
// Manual real-device QA checklist (written into results.json so a human
// can sign off on the parts Playwright cannot reliably exercise):
//   M1. Laptop "Pair phone" → offer QR appears within 5s and is sharp
//       enough that a phone camera can decode it from 30 cm.
//   M2. Phone scans the offer QR, opens the URL, auto-renders the answer
//       QR within 3s of page load.
//   M3. Laptop clicks "I scanned the QR — turn on camera"; camera-permission
//       prompt accepted; webcam preview appears.
//   M4. Laptop webcam decodes the phone's answer QR within 5s when pointed
//       at the phone screen; PairScreen state reaches `connected`.
//   M5. Phone "Send commit" → laptop shows "Last commit received at +Xms"
//       with X < 200.
//   M6. Camera-deny path: deny camera permission; PairScreen auto-flips to
//       manual mode with a "Camera blocked" banner.

import { chromium } from 'playwright'
import { mkdir, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { gzipSync } from 'node:zlib'

const BASE = 'http://localhost:5173/'
const OUT = resolve('../artifacts/phase-2b2-verify')

const consoleErrors = []

function log(...a) {
  console.log('[verify]', ...a)
}

async function screenshot(page, name) {
  const p = resolve(OUT, name)
  await page.screenshot({ path: p, fullPage: false })
  return p
}

async function clearIDB(page) {
  await page.evaluate(
    () =>
      new Promise((r) => {
        const req = indexedDB.deleteDatabase('pointfight-reactor')
        req.onsuccess = () => r()
        req.onerror = () => r()
        req.onblocked = () => r()
      }),
  )
}

function base64UrlEncode(bytes) {
  let bin = ''
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i])
  return Buffer.from(bin, 'binary')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '')
}

function makeOfferPayload(sdp) {
  return base64UrlEncode(gzipSync(Buffer.from(sdp, 'utf-8')))
}

async function isCanvasNonEmpty(page, selector) {
  return await page.evaluate((sel) => {
    const c = document.querySelector(sel)
    if (!c) return false
    const ctx = c.getContext('2d')
    if (!ctx) return false
    const w = c.width
    const h = c.height
    if (!w || !h) return false
    const data = ctx.getImageData(0, 0, w, h).data
    for (let i = 0; i < data.length; i += 4) {
      if (data[i] !== 255 || data[i + 1] !== 255 || data[i + 2] !== 255) {
        return true
      }
    }
    return false
  }, selector)
}

async function main() {
  await mkdir(OUT, { recursive: true })
  const browser = await chromium.launch()
  const results = {
    phase: 'phase-2b.2',
    startedAt: new Date().toISOString(),
    automated: {},
    manual_qa_checklist: [
      {
        id: 'M1',
        description:
          'Laptop "Pair phone" renders an offer QR within 5s, sharp enough for phone camera decode at ~30 cm.',
        signed_off: null,
      },
      {
        id: 'M2',
        description:
          'Phone scans the offer QR, opens the URL, auto-renders the answer QR within 3s of page load.',
        signed_off: null,
      },
      {
        id: 'M3',
        description:
          'Laptop "I scanned the QR — turn on camera" → permission prompt accepted, webcam preview visible.',
        signed_off: null,
      },
      {
        id: 'M4',
        description:
          'Laptop webcam decodes phone answer QR within 5s; PairScreen state reaches `connected`.',
        signed_off: null,
      },
      {
        id: 'M5',
        description:
          'Phone "Send commit" → laptop renders "Last commit received at +Xms" with X < 200.',
        signed_off: null,
      },
      {
        id: 'M6',
        description:
          'Camera-deny path: deny prompt; PairScreen auto-flips to manual mode with a "Camera blocked" banner.',
        signed_off: null,
      },
    ],
  }

  const sampleSdp = `v=0\no=- 4611731400430051336 2 IN IP4 127.0.0.1\ns=-\nt=0 0\na=group:BUNDLE 0\nm=application 9 UDP/DTLS/SCTP webrtc-datachannel\nc=IN IP4 0.0.0.0\na=ice-ufrag:abcd\na=ice-pwd:0123456789abcdef0123456789abcdef\na=fingerprint:sha-256 11:22:33:44:55:66:77:88:99:00:AA:BB:CC:DD:EE:FF:11:22:33:44:55:66:77:88:99:00:AA:BB:CC:DD:EE:FF\na=setup:actpass\na=mid:0\na=sctp-port:5000\n`
  const samplePayload = makeOfferPayload(sampleSdp)

  try {
    // ---------- C1. /phone without fragment → manual paste UI ----------
    {
      const ctx = await browser.newContext()
      const page = await ctx.newPage()
      page.on('console', (m) => {
        if (m.type() === 'error')
          consoleErrors.push(`[/phone-no-frag] ${m.text()}`)
      })
      await page.goto(BASE + 'phone')
      await page.waitForSelector('[aria-label="offer SDP"]')
      const offerTextarea = await page
        .locator('[aria-label="offer SDP"]')
        .count()
      results.automated.C1 = {
        pass: offerTextarea > 0,
        observed: { offerTextarea },
      }
      await screenshot(page, 'C1-no-fragment-manual.png')
      await ctx.close()
    }

    // ---------- C2. /phone#offer=<valid> → answer QR appears ----------
    {
      const ctx = await browser.newContext()
      const page = await ctx.newPage()
      page.on('console', (m) => {
        if (m.type() === 'error')
          consoleErrors.push(`[/phone-frag] ${m.text()}`)
      })
      await page.goto(`${BASE}phone#offer=${samplePayload}`)
      let qrAppeared = false
      try {
        await page.waitForSelector('[data-testid="answer-qr"]', {
          timeout: 15000,
        })
        // Allow QR to render onto the canvas after acceptOffer/encode.
        await page.waitForFunction(
          () => {
            const c = document.querySelector('[data-testid="answer-qr"]')
            return c && c.width > 0
          },
          { timeout: 5000 },
        )
        qrAppeared = await isCanvasNonEmpty(page, '[data-testid="answer-qr"]')
      } catch (e) {
        results.automated.C2_error = String(e)
      }
      results.automated.C2 = { pass: qrAppeared }
      await screenshot(page, 'C2-fragment-answer-qr.png')
      await ctx.close()
    }

    // ---------- C3. /phone#offer=<bad> → manual fallback + banner ----------
    {
      const ctx = await browser.newContext()
      const page = await ctx.newPage()
      page.on('console', (m) => {
        if (m.type() === 'error')
          consoleErrors.push(`[/phone-bad-frag] ${m.text()}`)
      })
      await page.goto(`${BASE}phone#offer=%21%21%21bad%21%21%21`)
      await page.waitForSelector('[data-testid="phone-fallback"]', {
        timeout: 10000,
      })
      const banner = await page
        .locator('[data-testid="phone-fallback"]')
        .textContent()
      const offerTextarea = await page
        .locator('[aria-label="offer SDP"]')
        .count()
      results.automated.C3 = {
        pass:
          offerTextarea > 0 && !!banner && /paste the offer manually/i.test(banner),
        banner,
      }
      await screenshot(page, 'C3-malformed-fragment.png')
      await ctx.close()
    }

    // ---------- C4. Pair view → QR mode default, QR canvas non-empty ----------
    {
      const ctx = await browser.newContext()
      const page = await ctx.newPage()
      page.on('console', (m) => {
        if (m.type() === 'error') consoleErrors.push(`[pair-qr] ${m.text()}`)
      })
      await page.goto(BASE)
      await clearIDB(page)
      await page.reload()
      await page.locator('button', { hasText: /Settings/i }).first().click()
      await page.locator('[aria-label="laptop LAN IP"]').fill('192.168.1.42')
      await page.locator('[aria-label="open pair phone"]').click()
      let qrCanvasNonEmpty = false
      let phoneUrl = ''
      try {
        await page.waitForSelector('[data-testid="offer-qr"]', {
          timeout: 15000,
        })
        await page.waitForFunction(
          () => {
            const c = document.querySelector('[data-testid="offer-qr"]')
            return c && c.width > 0
          },
          { timeout: 10000 },
        )
        qrCanvasNonEmpty = await isCanvasNonEmpty(
          page,
          '[data-testid="offer-qr"]',
        )
        phoneUrl =
          (await page
            .locator('[data-testid="phone-url"]')
            .textContent()) ?? ''
      } catch (e) {
        results.automated.C4_error = String(e)
      }
      results.automated.C4 = {
        pass:
          qrCanvasNonEmpty &&
          phoneUrl.includes('192.168.1.42') &&
          phoneUrl.includes('#offer='),
        qr_canvas_non_empty: qrCanvasNonEmpty,
        phone_url_starts_with: phoneUrl.slice(0, 80),
      }
      await screenshot(page, 'C4-pair-qr-mode.png')
      await ctx.close()
    }

    // ---------- C5. "Show manual pairing" toggle → manual textareas ----------
    {
      const ctx = await browser.newContext()
      const page = await ctx.newPage()
      page.on('console', (m) => {
        if (m.type() === 'error')
          consoleErrors.push(`[pair-toggle] ${m.text()}`)
      })
      await page.goto(BASE)
      await page.locator('button', { hasText: /Settings/i }).first().click()
      await page.locator('[aria-label="laptop LAN IP"]').fill('192.168.1.42')
      await page.locator('[aria-label="open pair phone"]').click()
      await page.waitForSelector('[aria-label="toggle pair mode"]')
      await page.locator('[aria-label="toggle pair mode"]').click()
      await page.waitForSelector('[aria-label="offer SDP"]')
      const manualTextareaVisible =
        (await page.locator('[aria-label="answer SDP"]').count()) > 0
      results.automated.C5 = { pass: manualTextareaVisible }
      await screenshot(page, 'C5-pair-manual-toggle.png')
      await ctx.close()
    }

    results.console_errors = consoleErrors
    results.finishedAt = new Date().toISOString()
    // C1, C3, C5 are gate-grade (run without a live WebRTC handshake).
    // C2 and C4 are best-effort: they require the in-browser peer to
    // complete ICE gathering, which headless chromium often cannot do on
    // loopback. The manual real-device QA checklist (M1–M6) is the
    // authoritative gate for the QR + WebRTC paths.
    const gateChecks = ['C1', 'C3', 'C5']
    const bestEffortChecks = ['C2', 'C4']
    results.summary = {
      gate_checks_pass: gateChecks.every((k) => results.automated[k]?.pass),
      best_effort_pass: bestEffortChecks.every(
        (k) => results.automated[k]?.pass,
      ),
      manual_qa_required: true,
      console_errors: consoleErrors.length,
    }
  } catch (e) {
    results.fatal = String(e)
    log('fatal:', e)
  } finally {
    await browser.close()
    await writeFile(
      resolve(OUT, 'results.json'),
      JSON.stringify(results, null, 2),
    )
    log('results written to', resolve(OUT, 'results.json'))
  }
}

