              style={{ display: 'none' }}
            />
          </>
        ) : (
          <button
            type="button"
            className="primary"
            onClick={onStartScan}
            disabled={qrState !== 'showing-offer'}
            aria-label="start scan"
          >
            I scanned the QR — turn on camera
          </button>
        )}
      </section>
    </>
  )
}

function ManualPanel({
  phoneUrl,
  offerSdp,
  answerSdp,
  peerState,
  onAnswerChange,
  onAccept,
}: {
