        )
        setFragmentDone(true)
        return
      }
      try {
        const peer = createPeer()
        peerRef.current = peer
        peer.onStateChange(setState)
        peer.onMessage(handlePeerMessage)
        const answerSdp = await peer.acceptOffer(dec.sdp)
        if (cancelled) return
        setAnswerText(answerSdp)
        const enc = await tryEncodeOffer(answerSdp)
        if (cancelled) return
        if (!enc.ok) {
          setMode('manual')
          setAutoFallbackReason(
            `Answer SDP is too large for one QR (${enc.byteLength} bytes) — copy it manually.`,
          )
          setFragmentDone(true)
          return
        }
        setAnswerPayload(enc.payload)
        setFragmentDone(true)
      } catch (e) {
        if (cancelled) return
        setMode('manual')
        setAutoFallbackReason(
          `Could not apply offer from QR (${e instanceof Error ? e.message : String(e)}) — paste it manually.`,
        )
        setFragmentDone(true)
      }
    })()
    return () => {
      cancelled = true
      peerRef.current?.close()
      detachMotionListener()
    }
    // handlePeerMessage / detachMotionListener are stable refs.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialOfferPayload])

  useEffect(() => {
    if (!answerPayload) return
    const canvas = answerQrRef.current
    if (!canvas) return
    void QRCode.toCanvas(canvas, answerPayload, {
      margin: 1,
      width: 320,
      errorCorrectionLevel: 'L',
    }).catch((e: unknown) => {
      setErr(e instanceof Error ? e.message : String(e))
    })
  }, [answerPayload])

  const ensureRunner = useCallback((): MotionRunner => {
    if (motionRunnerRef.current) return motionRunnerRef.current
    const runner = createMotionRunner({
      thresholdG: DEFAULT_THRESHOLD_G,
      debounceMs: DEFAULT_DEBOUNCE_MS,
      mode: 'armed',
    })
    motionRunnerRef.current = runner
    return runner
  }, [])

  const handlePeerMessage = useCallback(
    (m: PhoneMessage) => {
      if (m.type !== 'config') return
      // Laptop hands us the per-athlete threshold + mode. Reset the
      // detector via setConfig so the next swing fires immediately under
      // the new threshold.
      ensureRunner().setConfig({
        thresholdG: m.thresholdG,
        debounceMs: m.debounceMs,
        mode: m.mode,
      })
      setRunnerMode(m.mode)
    },
    [ensureRunner],
  )

  const detachMotionListener = useCallback((): void => {
    if (motionListenerRef.current && typeof window !== 'undefined') {
      window.removeEventListener('devicemotion', motionListenerRef.current)
    }
    motionListenerRef.current = null
  }, [])

  const attachMotionListener = useCallback((): void => {
    if (motionListenerRef.current) return
    if (typeof window === 'undefined') return
    const listener = (ev: DeviceMotionEvent) => {
      const sample = toMotionSample(ev)
      if (!sample) return
      const runner = ensureRunner()
      const msg = runner.push(sample)
      if (!msg) return
      const peakG = msg.type === 'sample' ? msg.peakG : undefined
      if (peakG !== undefined) setLastPeakG(peakG)
      try {
        peerRef.current?.send(msg)
        if (msg.type === 'commit') setLastCommitAt(msg.t)
      } catch {
        // The peer is closed/not-yet-open — drop the event. We could
        // queue, but the athlete cares about the most recent commit, not
        // any backlog accumulated while disconnected.
      }
    }
    motionListenerRef.current = listener
    window.addEventListener('devicemotion', listener)
  }, [ensureRunner])

  const handleEnableMotion = useCallback(async (): Promise<void> => {
    setMotionDenied(null)
    setErr(null)
    setMotionStatus('pending')
    const ctor = deviceMotionEventCtor()
    if (!ctor) {
      setMotionStatus('unsupported')
      setMotionDenied(
        'This device exposes no DeviceMotionEvent — motion commit is unavailable.',
      )
      return
    }
    if (typeof ctor.requestPermission === 'function') {
      try {
        const result = await ctor.requestPermission()
        if (result !== 'granted') {
          setMotionStatus('denied')
          setMotionDenied(
            'Motion permission was denied. On iOS this can be re-enabled in Settings → Safari → Motion & Orientation Access.',
          )
          return
        }
      } catch (e) {
        setMotionStatus('denied')
        setMotionDenied(
          `Could not request motion permission (${e instanceof Error ? e.message : String(e)}).`,
        )
        return
      }
    }
    ensureRunner()
    attachMotionListener()
    setMotionStatus('on')
  }, [attachMotionListener, ensureRunner])

  async function handleAcceptOffer(): Promise<void> {
    setErr(null)
    if (!offerText.trim()) {
      setErr('Paste the offer SDP from the laptop first.')
      return
    }
    if (peerRef.current) {
      setErr('Already paired this session — reload the page to start over.')
      return
    }
    try {
      const peer = createPeer()
      peerRef.current = peer
      peer.onStateChange(setState)
      peer.onMessage(handlePeerMessage)
      const answer = await peer.acceptOffer(offerText)
      setAnswerText(answer)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  function handleSendCommit(): void {
    setErr(null)
    const peer = peerRef.current
    if (!peer || state !== 'connected') {
      setErr('Not connected yet.')
      return
    }
    const t = Date.now()
    try {
      peer.send({ type: 'commit', t })
      setLastCommitAt(t)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  return (
    <div className="screen phone-app">
      <header>
        <h1>PointFight Phone Sensor</h1>
        <p className="hint">
          {mode === 'qr'
            ? 'QR pairing (Phase 2b.2). Show this screen to the laptop’s webcam.'
            : 'Manual pairing fallback.'}
        </p>
      </header>

      <div className="profile-actions">
        <button
          type="button"
          className="link"
          onClick={() => setMode((m) => (m === 'qr' ? 'manual' : 'qr'))}
          aria-label="toggle phone mode"
        >
          {mode === 'qr' ? 'Show manual paste' : 'Back to QR'}
        </button>
      </div>

      {autoFallbackReason && mode === 'manual' && (
        <div className="banner info" role="status" data-testid="phone-fallback">
          {autoFallbackReason}
        </div>
      )}

      {mode === 'qr' && fragmentDone && answerPayload && (
        <section className="settings-section">
          <h2>Show this QR to the laptop</h2>
          <canvas ref={answerQrRef} data-testid="answer-qr" />
          <p className="hint">
            The laptop's webcam will scan this to complete pairing.
          </p>
        </section>
      )}

      {mode === 'qr' && fragmentDone && !answerPayload && (
        <section className="settings-section">
          <p className="hint" data-testid="qr-pending">
            Open this page via the laptop's offer QR (URL contains{' '}
            <code>#offer=…</code>) to generate an answer QR.
          </p>
        </section>
      )}

      {mode === 'manual' && (
        <>
          <section className="settings-section">
            <h2>1. Paste the offer SDP from the laptop</h2>
            <textarea
              aria-label="offer SDP"
              rows={6}
              value={offerText}
              onChange={(e) => setOfferText(e.target.value)}
              placeholder="v=0…"
            />
            <button
              type="button"
              className="primary"
              onClick={() => void handleAcceptOffer()}
              disabled={state !== 'idle' && state !== 'error'}
            >
              Generate answer
            </button>
          </section>

          <section className="settings-section">
            <h2>2. Copy this answer back to the laptop</h2>
            <textarea
              aria-label="answer SDP"
              rows={6}
              value={answerText}
              readOnly
              placeholder="(generated after step 1)"
            />
          </section>
        </>
      )}

      <section className="settings-section">
        <h2>Motion sensor</h2>
        <p>
          Status:{' '}
          <strong data-testid="motion-status">{motionStatus}</strong>
          {motionStatus === 'on' && (
            <>
              {' '}(<span data-testid="motion-mode">{runnerMode}</span>)
            </>
          )}
        </p>
        {motionStatus !== 'on' && motionStatus !== 'unsupported' && (
          <button
            type="button"
            className="primary"
            onClick={() => void handleEnableMotion()}
            aria-label="enable motion sensor"
          >
            Enable motion sensor
          </button>
        )}
        {motionDenied && (
          <div
            className="banner warn"
            role="alert"
            data-testid="motion-denied"
          >
            {motionDenied}
          </div>
        )}
        {motionStatus === 'on' && lastPeakG !== null && (
          <p className="hint">
            Last detected peak:{' '}
            <strong data-testid="last-peak-g">{lastPeakG.toFixed(2)}</strong> g
          </p>
        )}
        <p className="hint">
          Once the motion sensor is on, the phone sends commits over the
          DataChannel automatically — you can stop using the manual button
          below.
        </p>
      </section>

      <section className="settings-section">
        <h2>Send a commit</h2>
        <p>
          Connection: <strong data-testid="phone-state">{state}</strong>
        </p>
        <button
          type="button"
          className="primary"
          onClick={handleSendCommit}
          disabled={state !== 'connected'}
        >
          Send commit (manual)
        </button>
        {lastCommitAt !== null && (
          <p className="hint">Last commit sent at {lastCommitAt}</p>
        )}
      </section>

      {err && (
        <div className="banner warn" role="alert">
          {err}
        </div>
      )}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import type { PeerHandle } from '../phone/peer'
import type { PhoneMessage } from '../phone/wire'
import {
  CALIBRATION_FLOOR_G,
  CALIBRATION_SAMPLE_COUNT,
  DEFAULT_DEBOUNCE_MS,
  DEFAULT_THRESHOLD_G,
  computeCalibrationThreshold,
} from '../phone/motion'
import type { ProfileRecord } from '../store/profiles'
import { saveProfile } from '../store/profiles'
import type { PhoneCalibration } from '../engine/types'

interface CalibrateScreenProps {
  peer: PeerHandle
  /** Active profile to write the calibrated threshold into. */
  profile: ProfileRecord
  /** Called with the freshly-saved profile when calibration completes. */
  onSaved: (next: ProfileRecord) => void
}

export type CalibrateStatus =
  | 'idle'
  | 'collecting'
  | 'done'
  | 'aborted'

export function CalibrateScreen({
  peer,
  profile,
  onSaved,
}: CalibrateScreenProps) {
  const [status, setStatus] = useState<CalibrateStatus>('idle')
  const [peaks, setPeaks] = useState<number[]>([])
  const [savedThreshold, setSavedThreshold] = useState<number | null>(null)
  const [err, setErr] = useState<string | null>(null)
  // Pin the previously calibrated threshold so the "current" readout doesn't
  // flicker once we save the new one and call onSaved().
  const initialThresholdRef = useRef<number | null>(
    profile.config.phoneCalibration?.thresholdG ?? null,
  )

  useEffect(() => {
    if (status !== 'collecting') return
    const off = peer.onMessage((m: PhoneMessage) => {
      if (m.type !== 'sample') return
      setPeaks((prev) => {
        if (prev.length >= CALIBRATION_SAMPLE_COUNT) return prev
        return [...prev, m.peakG]
      })
    })
    return off
  }, [peer, status])

  useEffect(() => {
    if (status !== 'collecting') return
    if (peaks.length < CALIBRATION_SAMPLE_COUNT) return
    void finishCalibration(peaks)
    // finishCalibration only depends on the captured peaks + the captured
    // profile + the captured peer; running once when the 5th peak lands.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [peaks, status])

  async function startCalibration(): Promise<void> {
    setErr(null)
    setPeaks([])
    setSavedThreshold(null)
    setStatus('collecting')
    try {
      peer.send({
        type: 'config',
        thresholdG: CALIBRATION_FLOOR_G,
        debounceMs: DEFAULT_DEBOUNCE_MS,
        mode: 'calibrating',
      })
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
      setStatus('aborted')
    }
  }

  async function finishCalibration(captured: number[]): Promise<void> {
    const thresholdG = computeCalibrationThreshold(captured)
    const calibration: PhoneCalibration = {
      thresholdG,
      calibratedAt: Date.now(),
    }
    const next: ProfileRecord = {
      ...profile,
      config: { ...profile.config, phoneCalibration: calibration },
    }
    try {
      await saveProfile(next)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
      setStatus('aborted')
      return
    }
    try {
      peer.send({
        type: 'config',
        thresholdG,
        debounceMs: DEFAULT_DEBOUNCE_MS,
        mode: 'armed',
      })
    } catch (e) {
      // Save succeeded; the phone just didn't get the new threshold
      // because the channel dropped. Surface it but keep the saved state.
      setErr(e instanceof Error ? e.message : String(e))
    }
    setSavedThreshold(thresholdG)
    setStatus('done')
    onSaved(next)
  }

  function reset(): void {
    setStatus('idle')
    setPeaks([])
    setErr(null)
  }

  const currentThreshold =
    savedThreshold ?? initialThresholdRef.current ?? DEFAULT_THRESHOLD_G
  const remaining = Math.max(0, CALIBRATION_SAMPLE_COUNT - peaks.length)

  return (
    <section
      className="settings-section"
      data-testid="calibrate-panel"
      aria-label="motion calibration"
    >
      <h2>Calibrate motion threshold</h2>
      <p className="hint">
        Throw {CALIBRATION_SAMPLE_COUNT} of your softest deliberate
        commit-strength swings — the laptop fits a per-athlete threshold
        from the captured peaks.
      </p>
      <p>
        Current threshold:{' '}
        <strong data-testid="calibrate-current">
          {currentThreshold.toFixed(2)} g
        </strong>
        {initialThresholdRef.current === null && (
          <em className="hint"> (default — not yet calibrated)</em>
        )}
      </p>

      {status === 'idle' && (
        <button
          type="button"
          className="primary"
          onClick={() => void startCalibration()}
          aria-label="start calibration"
        >
          Start calibration
        </button>
      )}

      {status === 'collecting' && (
        <div data-testid="calibrate-progress">
          <p>
            Captured {peaks.length} / {CALIBRATION_SAMPLE_COUNT}. Swings
            remaining: <strong>{remaining}</strong>.
          </p>
          {peaks.length > 0 && (
            <ul className="hint">
              {peaks.map((g, i) => (
                <li key={i}>
                  Sample {i + 1}: {g.toFixed(2)} g
                </li>
              ))}
            </ul>
          )}
          <button
            type="button"
            className="link"
            onClick={reset}
            aria-label="cancel calibration"
          >
            Cancel
          </button>
        </div>
      )}

      {status === 'done' && savedThreshold !== null && (
        <div data-testid="calibrate-done">
          <p>
            Saved threshold:{' '}
            <strong>{savedThreshold.toFixed(2)} g</strong>
          </p>
          <button
            type="button"
            className="link"
            onClick={reset}
            aria-label="recalibrate"
          >
            Re-run calibration
          </button>
        </div>
      )}

      {err && (
        <div className="banner warn" role="alert" data-testid="calibrate-error">
          {err}
        </div>
      )}
    </section>
  )
}

