1	export type PhoneMessage =
2	  | { type: 'commit'; t: number }
3	  | { type: 'ping'; t: number }
4	  | { type: 'sample'; t: number; peakG: number }
5	  | {
6	      type: 'config'
7	      thresholdG: number
8	      debounceMs: number
9	      mode: 'armed' | 'calibrating'
10	    }
11	
12	const SCALAR_T_TYPES = new Set<PhoneMessage['type']>(['commit', 'ping'])
13	const CONFIG_MODES = new Set<'armed' | 'calibrating'>(['armed', 'calibrating'])
14	
15	export function encodePhoneMessage(msg: PhoneMessage): string {
16	  return JSON.stringify(msg)
17	}
18	
19	export function decodePhoneMessage(raw: string): PhoneMessage | null {
20	  let parsed: unknown
21	  try {
22	    parsed = JSON.parse(raw)
23	  } catch {
24	    return null
25	  }
26	  return isPhoneMessage(parsed) ? parsed : null
27	}
28	
29	export function isPhoneMessage(v: unknown): v is PhoneMessage {
30	  if (typeof v !== 'object' || v === null) return false
31	  const o = v as Record<string, unknown>
32	  if (typeof o.type !== 'string') return false
33	  if (SCALAR_T_TYPES.has(o.type as PhoneMessage['type'])) {
34	    return typeof o.t === 'number'
35	  }
36	  if (o.type === 'sample') {
37	    return typeof o.t === 'number' && typeof o.peakG === 'number'
38	  }
39	  if (o.type === 'config') {
40	    return (
41	      typeof o.thresholdG === 'number' &&
42	      typeof o.debounceMs === 'number' &&
43	      typeof o.mode === 'string' &&
44	      CONFIG_MODES.has(o.mode as 'armed' | 'calibrating')
45	    )
46	  }
47	  return false
48	}
