66	export interface ImpulseDetector {
67	  /**
68	   * Feed one sample. Returns a `commit` event iff the magnitude is at or
69	   * above `thresholdG` and at least `debounceMs` has elapsed since the
70	   * previous emitted commit; otherwise null.
71	   */
72	  push(s: MotionSample): CommitEvent | null
73	  /** Forget the most recent commit so the next impulse can fire immediately. */
74	  reset(): void
75	}
76	
77	export function magnitudeG(s: {
78	  ax: number
79	  ay: number
80	  az: number
81	}): number {
82	  return Math.hypot(s.ax, s.ay, s.az) / G
83	}
84	
85	export function createImpulseDetector(opts: DetectorOptions): ImpulseDetector {
86	  let lastCommitAt: number | null = null
87	  return {
88	    push(s) {
89	      const g = magnitudeG(s)
90	      if (g < opts.thresholdG) return null
91	      if (lastCommitAt !== null && s.t - lastCommitAt < opts.debounceMs)
92	        return null
93	      lastCommitAt = s.t
94	      return { type: 'commit', t: s.t, peakG: g }
95	    },
96	    reset() {
97	      lastCommitAt = null
98	    },
99	  }
100	}

