  phoneUrl: string | null
  lanIp: string | null
  qrCanvasRef: React.RefObject<HTMLCanvasElement | null>
  videoRef: React.RefObject<HTMLVideoElement | null>
  canvasRef: React.RefObject<HTMLCanvasElement | null>
  onStartScan: () => void
}) {
  return (
