        ) : (
          <button
            type="button"
            className="primary"
            onClick={onStartScan}
            disabled={qrState !== 'showing-offer'}
            aria-label="start scan"
          >
            I scanned the QR — turn on camera
          </button>
        )}
      </section>
    </>
  )
}

function ManualPanel({
  phoneUrl,
  offerSdp,
  answerSdp,
  peerState,
  onAnswerChange,
  onAccept,
}: {
  phoneUrl: string | null
  offerSdp: string
  answerSdp: string
  peerState: PeerState
  onAnswerChange: (v: string) => void
  onAccept: () => void
}) {
  return (
    <>
      <section className="settings-section">
